dow: 0 28px 80px rgba(0, 0, 0, 0.56);\n}\n\n.reader-header {\n  padding: 13px 16px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  border-bottom: 1px solid var(--line-subtle);\n  background: var(--header-bg);\n}\n\n.reader-heading {\n  min-width: 0;\n  display: grid;\n  gap: 4px;\n\n  .reader-badge {\n    color: var(--gold);\n    font-size: 11px;\n    font-weight: 600;\n  }\n  h3 {\n    margin: 0;\n    overflow: hidden;\n    color: var(--text-accent);\n    font-size: 16px;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n}\n\n.reader-nav-actions {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.icon-btn {\n  width: 32px;\n  height: 32px;\n  display: grid;\n  place-items: center;\n  border: 1px solid var(--line-subtle);\n  border-radius: var(--radius-sm, 7px);\n  color: var(--text-secondary);\n  background: var(--surface-inset);\n  cursor: pointer;\n\n  &:hover:not(:disabled) {\n    border-color: var(--line-strong);\n    color: var(--gold);\n  }\n  &:disabled {\n    opacity: 0.35;\n    cursor: default;\n  }\n}\n\n.reader-body {\n  flex: 1 1 auto;\n  min-height: 0;\n  overflow-y: auto;\n  padding: 18px 22px;\n  display: grid;\n  align-content: start;\n  gap: 16px;\n  background: var(--paper-surface);\n}\n\n.reader-meta-banner {\n  padding: 10px 12px;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px 16px;\n  border: 1px solid var(--line-subtle);\n  border-radius: var(--radius-sm, 8px);\n  background: var(--surface-inset);\n  color: var(--text-secondary);\n  font-size: 12px;\n\n  strong {\n    color: var(--gold);\n    font-weight: 600;\n  }\n}\n\n.reader-prose {\n  display: grid;\n  gap: 13px;\n  color: var(--text-primary);\n  font-size: 15px;\n  line-height: 1.92;\n\n  p {\n    margin: 0;\n    text-indent: 2em;\n  }\n  .empty-prose {\n    text-indent: 0;\n    color: var(--text-secondary);\n  }\n}\n\n.reader-opportunities {\n  padding: 12px 14px;\n  border: 1px solid color-mix(in srgb, var(--gold) 34%, var(--line-subtle));\n  border-radius: var(--radius-sm, 8px);\n  background: color-mix(in srgb, var(--choice-surface) 88%, transparent);\n\n  h4 {\n    margin: 0 0 8px;\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    color: var(--gold);\n    font-size: 12.5px;\n  }\n  ul {\n    margin: 0;\n    padding-left: 18px;\n    display: grid;\n    gap: 5px;\n    color: var(--text-primary);\n    font-size: 12.5px;\n    line-height: 1.6;\n  }\n}\n\n.reader-footer {\n  padding: 11px 16px;\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 10px;\n  border-top: 1px solid var(--line-subtle);\n  background: var(--footer-bg);\n}\n\n.secondary-btn,\n.primary-btn {\n  min-height: 36px;\n  padding: 0 16px;\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  border-radius: var(--radius-sm, 8px);\n  font-size: 12.5px;\n  font-weight: 600;\n  cursor: pointer;\n}\n\n.secondary-btn {\n  border: 1px solid var(--line-subtle);\n  color: var(--text-secondary);\n  background: var(--surface-inset);\n}\n\n.primary-btn {\n  border: 1px solid color-mix(in srgb, var(--gold) 56%, var(--line-strong));\n  color: var(--text-accent);\n  background: var(--button-active);\n\n  i {\n    color: var(--gold);\n  }\n}\n\n.reader-fade-enter-active,\n.reader-fade-leave-active {\n  transition: opacity 0.16s ease;\n}\n.reader-fade-enter-from,\n.reader-fade-leave-to {\n  opacity: 0;\n}\n\n@media screen and (max-width: 680px) {\n  .reader-backdrop {\n    padding: 8px;\n  }\n  .reader-body {\n    padding: 14px;\n  }\n  .reader-prose {\n    font-size: 14px;\n  }\n}\n"],"sourceRoot":""}]);
