import { Schema } from '../灯火通明-测试版/schema';
const LAST_VALID_STAT_DATA_KEY = '__踏月寻仙_last_valid_stat_data';
const LAST_VALID_STAT_DATA_MESSAGE_ID_KEY = '__踏月寻仙_last_valid_stat_data_message_id';
const READING_POSITION_STORAGE_PREFIX = 'denghuolanshan:reading-position:';
function normalizeSpace(text) {
    return text.replace(/\s+/g, ' ').trim();
}
function normalizeForMatch(text) {
    return normalizeSpace(text).replace(/[\u200B-\u200D\uFEFF]/g, '');
}
function extractBracketTitle(text) {
    const firstLine = text
        .split('\n')
        .map(line => line.trim())
        .find(Boolean);
    const match = firstLine?.match(/^(?:\[(.+?)\]|【(.+?)】)/);
    return (match?.[1] ?? match?.[2])?.trim() ?? '';
}
function getFirstMessageContent() {
    const data = getCharData('current');
    if (!data)
        return '';
    const v2 = data.data;
    return String(v2?.first_mes ?? data.first_mes ?? '');
}
function findGreetingSwipeMessage() {
    try {
        const messages = getChatMessages('0-{{lastMessageId}}', { include_swipes: true });
        return messages.find(message => Array.isArray(message.swipes) && message.swipes.length > 1) ?? null;
    }
    catch {
        return null;
    }
}
export function resolveSwipeIdForOpening(target, swipes) {
    const normalizedTarget = normalizeForMatch(target.rawContent);
    let index = swipes.findIndex(swipe => normalizeForMatch(swipe) === normalizedTarget);
    if (index >= 0)
        return index;
    const targetTitle = extractBracketTitle(target.rawContent);
    if (targetTitle) {
        index = swipes.findIndex(swipe => extractBracketTitle(swipe) === targetTitle);
        if (index >= 0)
            return index;
    }
    const targetPrefix = normalizedTarget.slice(0, 120);
    if (targetPrefix) {
        index = swipes.findIndex(swipe => {
            const normalizedSwipe = normalizeForMatch(swipe);
            return normalizedSwipe.includes(targetPrefix) || targetPrefix.includes(normalizedSwipe.slice(0, 120));
        });
        if (index >= 0)
            return index;
    }
    const normalizedFirstMessage = normalizeForMatch(getFirstMessageContent());
    const normalizedFirstSwipe = normalizeForMatch(swipes[0] ?? '');
    const includesFirstMessage = normalizedFirstMessage.length > 0 &&
        normalizedFirstSwipe.length > 0 &&
        (normalizedFirstSwipe === normalizedFirstMessage ||
            normalizedFirstSwipe.includes(normalizedFirstMessage.slice(0, 120)) ||
            normalizedFirstMessage.includes(normalizedFirstSwipe.slice(0, 120)));
    const fallbackIndex = target.index - 1 + (includesFirstMessage ? 1 : 0);
    return fallbackIndex >= 0 && fallbackIndex < swipes.length ? fallbackIndex : null;
}
export function readGreetingChatRuntimeState(openings) {
    const greetingMessage = findGreetingSwipeMessage();
    let lastMessageId = -1;
    try {
        const id = getLastMessageId();
        if (typeof id === 'number' && Number.isFinite(id)) {
            lastMessageId = id;
        }
    }
    catch {
        lastMessageId = -1;
    }
    if (!greetingMessage) {
        return {
            hasSwipeFloor: false,
            greetingMessageId: 0,
            currentSwipeId: null,
            currentIndex: null,
            lastMessageId,
            laterMessageCount: Math.max(0, lastMessageId),
        };
    }
    const currentSwipeId = Number.isInteger(greetingMessage.swipe_id) ? Number(greetingMessage.swipe_id) : null;
    const matched = currentSwipeId === null
        ? undefined
        : openings.find(item => resolveSwipeIdForOpening(item, greetingMessage.swipes) === currentSwipeId);
    const laterMessageCount = Math.max(0, lastMessageId - greetingMessage.message_id);
    return {
        hasSwipeFloor: true,
        greetingMessageId: greetingMessage.message_id,
        currentSwipeId,
        currentIndex: matched?.index ?? null,
        lastMessageId,
        laterMessageCount,
    };
}
function clearStaleChatSnapshots() {
    try {
        const chatVariables = klona(getVariables({ type: 'chat' }) ?? {});
        let changed = false;
        if (LAST_VALID_STAT_DATA_KEY in chatVariables) {
            delete chatVariables[LAST_VALID_STAT_DATA_KEY];
            changed = true;
        }
        if (LAST_VALID_STAT_DATA_MESSAGE_ID_KEY in chatVariables) {
            delete chatVariables[LAST_VALID_STAT_DATA_MESSAGE_ID_KEY];
            changed = true;
        }
        if (changed) {
            replaceVariables(chatVariables, { type: 'chat' });
        }
    }
    catch (error) {
        console.warn('[开场白索引] 清理聊天变量快照失败', error);
    }
    try {
        const chatId = String(SillyTavern.getCurrentChatId?.() ?? '');
        const storage = window.parent?.sessionStorage ?? window.sessionStorage;
        if (chatId && storage) {
            storage.removeItem(READING_POSITION_STORAGE_PREFIX + chatId);
        }
    }
    catch {
        // ignore storage access errors
    }
}
async function prepareOpeningMvuData(rawContent, savedData) {
    await waitGlobalInitialized('Mvu');
    const activeContent = substitudeMacros(rawContent);
    const baseData = klona(savedData);
    const initBlocks = [...activeContent.matchAll(/<initvar\b[^>]*>([\s\S]*?)<\/initvar\s*>/gi)];
    // parseMessage 只执行变量更新指令，开局的 YAML 初始值需要先载入解析基底。
    if (initBlocks.length > 0) {
        const initialValues = {};
        for (const block of initBlocks) {
            const yaml = block[1].trim().replace(/^```[^\n]*\n([\s\S]*?)\n```\s*$/, '$1');
            const values = YAML.parse(yaml);
            if (!values || typeof values !== 'object' || Array.isArray(values)) {
                throw new Error('开局初始变量必须是 YAML 对象');
            }
            _.merge(initialValues, values);
        }
        baseData.stat_data = Schema.parse(initialValues);
    }
    else {
        baseData.stat_data = Schema.parse(baseData.stat_data ?? {});
    }
    baseData.initialized_lorebooks ??= {};
    const parsedData = await Mvu.parseMessage(activeContent, baseData);
    parsedData.stat_data = Schema.parse(parsedData.stat_data);
    return parsedData;
}
export async function executeSwitchOpening(target, options = {}) {
    const greetingMessage = findGreetingSwipeMessage();
    if (!greetingMessage) {
        toastr.error('未找到可切换的开场白楼层，请先进入角色聊天并确认开场白已生成。');
        return false;
    }
    const swipeId = resolveSwipeIdForOpening(target, greetingMessage.swipes);
    if (swipeId === null) {
        toastr.error('未能定位对应开场白，建议先在酒馆原生切换一次开场后重试。');
        return false;
    }
    const lastMessageId = getLastMessageId();
    if (typeof lastMessageId === 'number' && lastMessageId > greetingMessage.message_id) {
        if (!options.clearLaterMessages) {
            toastr.warning('当前聊天已有后续推演楼层，请确认清空后再切换开局。');
            return false;
        }
    }
    // 在刷新舞台及清理后续楼层前完成初始化，避免界面先读到空变量或解析失败后丢失聊天。
    const swipesData = klona(greetingMessage.swipes_data);
    swipesData[swipeId] = await prepareOpeningMvuData(greetingMessage.swipes[swipeId], swipesData[swipeId] ?? {});
    let deletedLaterFloors = false;
    if (typeof lastMessageId === 'number' && lastMessageId > greetingMessage.message_id) {
        const idsToDelete = [];
        for (let id = greetingMessage.message_id + 1; id <= lastMessageId; id += 1) {
            idsToDelete.push(id);
        }
        if (idsToDelete.length > 0) {
            await deleteChatMessages(idsToDelete, { refresh: 'none' });
            deletedLaterFloors = true;
        }
    }
    clearStaleChatSnapshots();
    // 第 0 层内互跳使用 affected 刷新，避免触发 CHAT_CHANGED 销毁伪同层常驻舞台导致整页冷重启；
    // 仅在删除了后续推演楼层时使用 all 刷新完整重建聊天状态。
    await setChatMessages([
        {
            message_id: greetingMessage.message_id,
            swipe_id: swipeId,
            swipes_data: swipesData,
        },
    ], { refresh: deletedLaterFloors ? 'all' : 'affected' });
    await eventEmit(tavern_events.MESSAGE_SWIPED, greetingMessage.message_id);
    await eventEmit(tavern_events.MESSAGE_UPDATED, greetingMessage.message_id);
    const label = target.subtitle ? target.shortTitle + ' · ' + target.subtitle : target.title;
    toastr.success('已切换至「' + label + '」', '开场白索引');
    return true;
}
